  whyWeBuiltPara1: "La plupart des sites de livres sont soit un catalogue statique sans profondeur, soit une plateforme d'avis coincée dans la décennie passée avec des pages encombrées et aucun véritable outil de découverte. Nous voulions quelque chose de différent : une plateforme où vous pouvez décider d'un livre en cinq minutes, suivre votre lecture honnêtement, et vraiment vous connecter avec d'autres lecteurs — pas seulement laisser une note en étoiles dans le vide.",
