  aboutMetaTitle: "概要",
  aboutMetaDesc: "BookQubitは、次の名著をより速く見つけるための読書プラットフォームです——要約、要点、コミュニティレビュー、読書トラッキング、ブックワームランキングを21言語で提供します。",
  aboutHeroTitle: "BookQubitについて",
  aboutHeroSub: "一つの理念のもとに作られた読書プラットフォーム：次の名著をより速く見つける手助けをし、その周りに本物の読書ライフを提供する——単なる静的なカタログではありません。",
  whyWeBuiltTitle: "私たちがこれを作った理由",
  whyWeBuiltPara1: "ほとんどの読書サイトは、深みのない静的なカタログか、乱雑なページと本物の発見ツールを欠いた、過去の年代に取り残されたレビュープラットフォームのどちらかです。私たちは違うものを求めました：5分で本について判断でき、正直に読書を記録し、実際に他の読者とつながれるプラットフォーム——虚空に星評価を残すだけではなく。",
  whyWeBuiltPara2: "すべての本のページは、あなたが素早く判断できるように作られています：本物の要約、要点、コミュニティの雰囲気（評価、ムード、ペース）、そして購入や視聴への直接的な道——読んだ後に進捗を追跡し、自分のレビューを書くツールも備えています。",
  whatYouCanDoTitle: "ここでできること",
  featSummariesTitle: "5分の要約",
  featSummariesDesc: "すべての本には簡潔な要約と要点が付いているので、数分でその本があなたの時間に見合うかどうか判断できます。",
  featReviewsTitle: "本物のコミュニティレビュー",
