  whyWeBuiltTitle: "Warum wir das gebaut haben",
  whyWeBuiltPara1: "Die meisten Buchseiten sind entweder ein statischer Katalog ohne Tiefe oder eine Bewertungsplattform, die im letzten Jahrzehnt steckengeblieben ist, mit überladenen Seiten und ohne echte Entdeckungswerkzeuge. Wir wollten etwas anderes: eine Plattform, auf der du dich in fünf Minuten für ein Buch entscheiden, deine Lektüre ehrlich verfolgen und dich wirklich mit anderen Lesern vernetzen kannst — nicht nur eine Sternebewertung ins Leere abgeben.",
  whyWeBuiltPara2: "Jede Buchseite ist darauf ausgelegt, dir eine schnelle Entscheidung zu ermöglichen: eine echte Zusammenfassung, Kernaussagen, Community-Stimmung (Bewertungen, Stimmungen, Tempo) und ein direkter Weg zum Kaufen oder Anhören — gefolgt von Werkzeugen, um deinen Fortschritt zu verfolgen und deine eigene Rezension zu schreiben, sobald du es gelesen hast.",
