  aboutMetaTitle: "আমাদের সম্পর্কে",
  aboutMetaDesc: "বুককিউবিট একটি রিডিং প্ল্যাটফর্ম যা আপনাকে দ্রুত আপনার পরবর্তী দুর্দান্ত বই খুঁজে পেতে সাহায্য করে — সারাংশ, মূল বিষয়, কমিউনিটি পর্যালোচনা, পঠন ট্র্যাকিং এবং একটি বুকওয়ার্ম র‍্যাঙ্কিং, ২১টি ভাষায়।",
  aboutHeroTitle: "বুককিউবিট সম্পর্কে",
  aboutHeroSub: "একটি ধারণাকে কেন্দ্র করে তৈরি একটি রিডিং প্ল্যাটফর্ম: আপনাকে দ্রুত আপনার পরবর্তী দুর্দান্ত বই খুঁজে পেতে সাহায্য করা, এবং তার চারপাশে একটি প্রকৃত পঠন জীবন দেওয়া — শুধু একটি স্থির ক্যাটালগ নয়।",
  whyWeBuiltTitle: "আমরা কেন এটি তৈরি করেছি",
  whyWeBuiltPara1: "বেশিরভাগ বইয়ের সাইট হয় গভীরতাহীন একটি স্থির ক্যাটালগ, অথবা বিশৃঙ্খল পৃষ্ঠা এবং কোনো প্রকৃত আবিষ্কার সরঞ্জাম ছাড়া গত দশকে আটকে থাকা একটি পর্যালোচনা প্ল্যাটফর্ম। আমরা কিছু আলাদা চেয়েছিলাম: এমন একটি প্ল্যাটফর্ম যেখানে আপনি পাঁচ মিনিটে একটি বই সম্পর্কে সিদ্ধান্ত নিতে পারেন, সততার সাথে আপনার পড়া ট্র্যাক করতে পারেন, এবং সত্যিই অন্য পাঠকদের সাথে সংযুক্ত হতে পারেন — শুধু শূন্যে একটি স্টার রেটিং রেখে যাওয়া নয়।",
  whyWeBuiltPara2: "প্রতিটি বইয়ের পৃষ্ঠা আপনাকে দ্রুত সিদ্ধান্ত নিতে সাহায্য করার জন্য তৈরি: একটি প্রকৃত সারাংশ, মূল বিষয়, কমিউনিটির অনুভূতি (রেটিং, মেজাজ, গতি), এবং কেনা বা শোনার একটি সরাসরি পথ — পড়ার পর আপনার অগ্রগতি ট্র্যাক করতে এবং নিজের পর্যালোচনা লিখতে সরঞ্জাম সহ।",
