  whyWeBuiltPara1: "பெரும்பாலான புத்தக தளங்கள் ஆழமற்ற ஒரு நிலையான பட்டியலாக அல்லது குழப்பமான பக்கங்களுடன், உண்மையான கண்டுபிடிப்பு கருவிகள் இல்லாமல் கடந்த தசாப்தத்தில் சிக்கிய ஒரு விமர்சன தளமாக இருக்கும். நாங்கள் வேறுபட்ட ஒன்றை விரும்பினோம்: ஐந்து நிமிடங்களில் ஒரு புத்தகத்தைப் பற்றி முடிவெடுக்கவும், நேர்மையாக உங்கள் வாசிப்பைக் கண்காணிக்கவும், மற்றும் மற்ற வாசகர்களுடன் உண்மையிலேயே இணையவும் முடியும் — வெறும் வெற்றிடத்தில் ஒரு நட்சத்திர மதிப்பீட்டை விட்டுவிடுவதற்குப் பதிலாக.",
  whyWeBuiltPara2: "ஒவ்வொரு புத்தக பக்கமும் நீங்கள் விரைவாக முடிவெடுக்க உதவும் வகையில் உருவாக்கப்பட்டுள்ளது: ஒரு உண்மையான சுருக்கம், முக்கிய குறிப்புகள், சமூக உணர்வு (மதிப்பீடுகள், மனநிலைகள், வேகம்), மற்றும் வாங்க அல்லது கேட்க ஒரு நேரடி வழி — படித்த பிறகு உங்கள் முன்னேற்றத்தைக் கண்காணிக்கவும் உங்கள் சொந்த விமர்சனத்தை எழுதவும் கருவிகளுடன்.",
