  aboutMetaDesc: "బుక్‌క్యూబిట్ అనేది మీ తదుపరి గొప్ప పుస్తకాన్ని వేగంగా కనుగొనడంలో సహాయపడే రీడింగ్ ప్లాట్‌ఫారమ్ — సారాంశాలు, ముఖ్యాంశాలు, కమ్యూనిటీ సమీక్షలు, రీడింగ్ ట్రాకింగ్ మరియు బుక్‌వార్మ్ ర్యాంకింగ్, 21 భాషల్లో.",
  aboutHeroTitle: "బుక్‌క్యూబిట్ గురించి",
  aboutHeroSub: "ఒకే ఆలోచన చుట్టూ నిర్మించబడిన రీడింగ్ ప్లాట్‌ఫారమ్: మీ తదుపరి గొప్ప పుస్తకాన్ని వేగంగా కనుగొనడంలో సహాయపడటం, మరియు దాని చుట్టూ నిజమైన పఠన జీవితాన్ని అందించడం — కేవలం ఒక స్థిర జాబితా కాదు.",
  whyWeBuiltTitle: "మేము దీన్ని ఎందుకు నిర్మించాము",
  whyWeBuiltPara1: "చాలా పుస్తక సైట్‌లు లోతు లేని స్థిర జాబితా లేదా చిందరవందర పేజీలు మరియు నిజమైన అన్వేషణ సాధనాలు లేకుండా గత దశాబ్దంలో ఇరుక్కుపోయిన సమీక్ష ప్లాట్‌ఫారమ్. మేము వేరే విషయాన్ని కోరుకున్నాము: ఐదు నిమిషాల్లో పుస్తకం గురించి నిర్ణయించుకోగల, నిజాయితీగా మీ పఠనాన్ని ట్రాక్ చేయగల, మరియు నిజంగా ఇతర పాఠకులతో కనెక్ట్ అవ్వగల ప్లాట్‌ఫారమ్ — శూన్యంలో స్టార్ రేటింగ్ వదిలేయడం కాదు.",
  whyWeBuiltPara2: "ప్రతి పుస్తక పేజీ మిమ్మల్ని వేగంగా నిర్ణయం తీసుకునేలా చేయడానికి రూపొందించబడింది: నిజమైన సారాంశం, ముఖ్యాంశాలు, కమ్యూనిటీ భావన (రేటింగ్‌లు, మూడ్‌లు, వేగం), మరియు కొనుగోలు చేయడానికి లేదా వినడానికి ప్రత్యక్ష మార్గం — చదివిన తర్వాత మీ పురోగతిని ట్రాక్ చేయడానికి మరియు మీ స్వంత సమీక్ష రాయడానికి సాధనాలతో పాటు.",
