  aboutHeroSub: "એક વિચાર પર બનેલું રીડિંગ પ્લેટફોર્મ: તમને તમારું આગલું શ્રેષ્ઠ પુસ્તક ઝડપથી શોધવામાં મદદ કરવી, અને તેની આસપાસ એક વાસ્તવિક વાંચન જીવન આપવું — ફક્ત એક સ્થિર સૂચિ નહીં.",
  whyWeBuiltTitle: "અમે આ કેમ બનાવ્યું",
  whyWeBuiltPara1: "મોટાભાગની પુસ્તક સાઇટ્સ કાં તો ઊંડાણ વગરની સ્થિર સૂચિ છે, અથવા અવ્યવસ્થિત પૃષ્ઠો અને કોઈ વાસ્તવિક શોધ સાધનો વિના ભૂતકાળના દાયકામાં અટવાયેલ સમીક્ષા પ્લેટફોર્મ છે. અમને કંઈક અલગ જોઈતું હતું: એક એવું પ્લેટફોર્મ જ્યાં તમે પાંચ મિનિટમાં પુસ્તક વિશે નિર્ણય લઈ શકો, પ્રામાણિકપણે તમારું વાંચન ટ્રેક કરી શકો, અને ખરેખર અન્ય વાચકો સાથે જોડાઈ શકો — ફક્ત શૂન્યાવકાશમાં સ્ટાર રેટિંગ છોડવાને બદલે.",
  whyWeBuiltPara2: "દરેક પુસ્તક પૃષ્ઠ તમને ઝડપથી નિર્ણય લેવામાં મદદ કરવા માટે બનાવવામાં આવ્યું છે: એક વાસ્તવિક સારાંશ, મુખ્ય મુદ્દા, સમુદાય ભાવના (રેટિંગ, મૂડ, ગતિ), અને ખરીદવા અથવા સાંભળવાનો સીધો માર્ગ — વાંચ્યા પછી તમારી પ્રગતિ ટ્રેક કરવા અને તમારી પોતાની સમીક્ષા લખવા માટેના સાધનો સાથે.",
