  whyWeBuiltTitle: "ನಾವು ಇದನ್ನು ಏಕೆ ನಿರ್ಮಿಸಿದ್ದೇವೆ",
  whyWeBuiltPara1: "ಹೆಚ್ಚಿನ ಪುಸ್ತಕ ಸೈಟ್‌ಗಳು ಆಳವಿಲ್ಲದ ಸ್ಥಿರ ಪಟ್ಟಿ ಅಥವಾ ಗೊಂದಲಮಯ ಪುಟಗಳು ಮತ್ತು ನಿಜವಾದ ಅನ್ವೇಷಣಾ ಸಾಧನಗಳಿಲ್ಲದೆ ಹಿಂದಿನ ದಶಕದಲ್ಲಿ ಸಿಲುಕಿರುವ ವಿಮರ್ಶಾ ವೇದಿಕೆಯಾಗಿದೆ. ನಮಗೆ ಬೇರೆಯದೇ ಬೇಕಿತ್ತು: ಐದು ನಿಮಿಷಗಳಲ್ಲಿ ಪುಸ್ತಕದ ಬಗ್ಗೆ ನಿರ್ಧರಿಸಬಹುದಾದ, ಪ್ರಾಮಾಣಿಕವಾಗಿ ನಿಮ್ಮ ಓದುವಿಕೆಯನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಬಹುದಾದ ಮತ್ತು ನಿಜವಾಗಿಯೂ ಇತರ ಓದುಗರೊಂದಿಗೆ ಸಂಪರ್ಕ ಸಾಧಿಸಬಹುದಾದ ವೇದಿಕೆ — ಬರಿ ಶೂನ್ಯದಲ್ಲಿ ನಕ್ಷತ್ರ ರೇಟಿಂಗ್ ಬಿಡುವ ಬದಲು.",
  whyWeBuiltPara2: "ಪ್ರತಿ ಪುಸ್ತಕ ಪುಟವು ನಿಮ್ಮನ್ನು ವೇಗವಾಗಿ ನಿರ್ಧಾರಕ್ಕೆ ತರಲು ನಿರ್ಮಿಸಲಾಗಿದೆ: ನಿಜವಾದ ಸಾರಾಂಶ, ಮುಖ್ಯಾಂಶಗಳು, ಸಮುದಾಯ ಭಾವನೆ (ರೇಟಿಂಗ್‌ಗಳು, ಮೂಡ್‌ಗಳು, ವೇಗ), ಮತ್ತು ಖರೀದಿಸಲು ಅಥವಾ ಕೇಳಲು ನೇರ ಮಾರ್ಗ — ಓದಿದ ನಂತರ ನಿಮ್ಮ ಪ್ರಗತಿಯನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಲು ಮತ್ತು ನಿಮ್ಮ ಸ್ವಂತ ವಿಮರ್ಶೆ ಬರೆಯಲು ಸಾಧನಗಳೊಂದಿಗೆ.",
  whatYouCanDoTitle: "ನೀವು ಇಲ್ಲಿ ಏನು ಮಾಡಬಹುದು",
  featSummariesTitle: "5-ನಿಮಿಷದ ಸಾರಾಂಶಗಳು",
  featSummariesDesc: "ಪ್ರತಿ ಪುಸ್ತಕವು ಸಂಕ್ಷಿಪ್ತ ಸಾರಾಂಶ ಮತ್ತು ಮುಖ್ಯಾಂಶಗಳೊಂದಿಗೆ ಬರುತ್ತದೆ, ಆದ್ದರಿಂದ ಅದು ನಿಮ್ಮ ಸಮಯಕ್ಕೆ ಯೋಗ್ಯವಾಗಿದೆಯೇ ಎಂದು ನೀವು ನಿಮಿಷಗಳಲ್ಲಿ ನಿರ್ಧರಿಸಬಹುದು.",
