  filteredOfTotalBooks: "{total} ൽ {filtered} പുസ്തകങ്ങൾ",
  noBooksFoundLabel: "പുസ്തകങ്ങളൊന്നും കണ്ടെത്തിയില്ല.",
  aboutMetaTitle: "ഞങ്ങളെക്കുറിച്ച്",
  aboutMetaDesc: "നിങ്ങളുടെ അടുത്ത മികച്ച പുസ്തകം വേഗത്തിൽ കണ്ടെത്താൻ സഹായിക്കുന്ന വായനാ പ്ലാറ്റ്‌ഫോമാണ് ബുക്ക്ക്യൂബിറ്റ് — സംഗ്രഹങ്ങൾ, പ്രധാന കാര്യങ്ങൾ, കമ്മ്യൂണിറ്റി അവലോകനങ്ങൾ, വായന ട്രാക്കിംഗ്, ബുക്ക്‌വേം റാങ്കിംഗ്, 21 ഭാഷകളിൽ.",
  aboutHeroTitle: "ബുക്ക്ക്യൂബിറ്റിനെക്കുറിച്ച്",
  aboutHeroSub: "ഒരു ആശയത്തിന് ചുറ്റും നിർമ്മിച്ച വായനാ പ്ലാറ്റ്‌ഫോം: നിങ്ങളുടെ അടുത്ത മികച്ച പുസ്തകം വേഗത്തിൽ കണ്ടെത്താൻ സഹായിക്കുക, അതിന് ചുറ്റും ഒരു യഥാർത്ഥ വായനാ ജീവിതം നൽകുക — വെറും നിശ്ചല കാറ്റലോഗ് അല്ല.",
  whyWeBuiltTitle: "ഞങ്ങൾ ഇത് നിർമ്മിച്ചത് എന്തുകൊണ്ട്",
  whyWeBuiltPara1: "മിക്ക പുസ്തക സൈറ്റുകളും ആഴമില്ലാത്ത നിശ്ചല കാറ്റലോഗ് അല്ലെങ്കിൽ ക്രമരഹിതമായ പേജുകളും യഥാർത്ഥ കണ്ടെത്തൽ ഉപകരണങ്ങളും ഇല്ലാതെ കഴിഞ്ഞ ദശകത്തിൽ കുടുങ്ങിക്കിടക്കുന്ന ഒരു അവലോകന പ്ലാറ്റ്‌ഫോമാണ്. ഞങ്ങൾക്ക് വ്യത്യസ്തമായ എന്തെങ്കിലും വേണമായിരുന്നു: അഞ്ച് മിനിറ്റിനുള്ളിൽ ഒരു പുസ്തകത്തെക്കുറിച്ച് തീരുമാനിക്കാനും, സത്യസന്ധമായി നിങ്ങളുടെ വായന ട്രാക്ക് ചെയ്യാനും, മറ്റ് വായനക്കാരുമായി യഥാർത്ഥത്തിൽ ബന്ധപ്പെടാനും കഴിയുന്ന ഒരു പ്ലാറ്റ്‌ഫോം — ശൂന്യതയിലേക്ക് ഒരു സ്റ്റാർ റേറ്റിംഗ് ഇടുന്നതിന് പകരം.",
  whyWeBuiltPara2: "ഓരോ പുസ്തക പേജും നിങ്ങളെ വേഗത്തിൽ തീരുമാനത്തിലെത്തിക്കാൻ നിർമ്മിച്ചതാണ്: ഒരു യഥാർത്ഥ സംഗ്രഹം, പ്രധാന കാര്യങ്ങൾ, കമ്മ്യൂണിറ്റി വികാരം (റേറ്റിംഗുകൾ, മൂഡുകൾ, വേഗത), കൂടാതെ വാങ്ങാനോ കേൾക്കാനോ ഉള്ള നേരിട്ടുള്ള വഴി — വായിച്ചതിനുശേഷം നിങ്ങളുടെ പുരോഗതി ട്രാക്ക് ചെയ്യാനും സ്വന്തം അവലോകനം എഴുതാനുമുള്ള ഉപകരണങ്ങളോടെ.",
  whatYouCanDoTitle: "നിങ്ങൾക്ക് ഇവിടെ എന്ത് ചെയ്യാൻ കഴിയും",
  featSummariesTitle: "5 മിനിറ്റ് സംഗ്രഹങ്ങൾ",
  featSummariesDesc: "ഓരോ പുസ്തകത്തിനും ഒരു സംക്ഷിപ്ത സംഗ്രഹവും പ്രധാന കാര്യങ്ങളും ഉണ്ട്, അതിനാൽ അത് നിങ്ങളുടെ സമയത്തിന് യോഗ്യമാണോ എന്ന് മിനിറ്റുകൾക്കുള്ളിൽ തീരുമാനിക്കാം.",
  featReviewsTitle: "യഥാർത്ഥ കമ്മ്യൂണിറ്റി അവലോകനങ്ങൾ",
  featReviewsDesc: "യഥാർത്ഥ വായനക്കാരിൽ നിന്നുള്ള റേറ്റിംഗുകൾ, എഴുതിയ അവലോകനങ്ങൾ, മൂഡ്/വേഗത ടാഗുകൾ — സന്ദർഭമില്ലാത്ത ഒരു സ്റ്റാർ ശരാശരി മാത്രമല്ല.",
  featShelfTitle: "ഓർമ്മിക്കുന്ന ഷെൽഫ്",
  featShelfDesc: "നിങ്ങൾ എന്ത് വായിക്കാൻ ആഗ്രഹിക്കുന്നു, ഇപ്പോൾ എന്ത് വായിക്കുന്നു (പുരോഗതിയോടെ), എന്ത് പൂർത്തിയാക്കി എന്നിവ ട്രാക്ക് ചെയ്യുക — എല്ലാം നിങ്ങളുടെ അക്കൗണ്ടുമായി സമന്വയിപ്പിച്ചിരിക്കുന്നു.",
  featRankingTitle: "ബുക്ക്‌വേം റാങ്കിംഗ്",
  featRankingDesc: "വായിച്ച പുസ്തകങ്ങൾ, എഴുതിയ അവലോകനങ്ങൾ, കമ്മ്യൂണിറ്റി പങ്കാളിത്തം എന്നിവയ്ക്ക് പോയിന്റുകൾ നേടുക. വായിക്കുമ്പോൾ ലീഡർബോർഡിൽ കയറുക.",
  featCommunityTitle: "കമ്മ്യൂണിറ്റി ചർച്ചകൾ",
