  aboutHeroSub: "ਇੱਕ ਵਿਚਾਰ ਦੁਆਲੇ ਬਣਾਇਆ ਗਿਆ ਰੀਡਿੰਗ ਪਲੇਟਫਾਰਮ: ਤੁਹਾਨੂੰ ਤੁਹਾਡੀ ਅਗਲੀ ਵਧੀਆ ਕਿਤਾਬ ਤੇਜ਼ੀ ਨਾਲ ਲੱਭਣ ਵਿੱਚ ਮਦਦ ਕਰਨਾ, ਅਤੇ ਇਸਦੇ ਆਲੇ-ਦੁਆਲੇ ਇੱਕ ਅਸਲੀ ਰੀਡਿੰਗ ਜ਼ਿੰਦਗੀ ਦੇਣਾ — ਸਿਰਫ਼ ਇੱਕ ਸਥਿਰ ਕੈਟਾਲਾਗ ਨਹੀਂ।",
  whyWeBuiltTitle: "ਅਸੀਂ ਇਹ ਕਿਉਂ ਬਣਾਇਆ",
  whyWeBuiltPara1: "ਜ਼ਿਆਦਾਤਰ ਕਿਤਾਬ ਸਾਈਟਾਂ ਜਾਂ ਤਾਂ ਡੂੰਘਾਈ ਤੋਂ ਬਿਨਾਂ ਇੱਕ ਸਥਿਰ ਕੈਟਾਲਾਗ ਹਨ, ਜਾਂ ਗੜਬੜ ਵਾਲੇ ਪੰਨਿਆਂ ਅਤੇ ਕੋਈ ਅਸਲੀ ਖੋਜ ਸੰਦ ਨਾ ਹੋਣ ਦੇ ਨਾਲ ਪਿਛਲੇ ਦਹਾਕੇ ਵਿੱਚ ਫਸਿਆ ਸਮੀਖਿਆ ਪਲੇਟਫਾਰਮ ਹੈ। ਅਸੀਂ ਕੁਝ ਵੱਖਰਾ ਚਾਹੁੰਦੇ ਸੀ: ਇੱਕ ਅਜਿਹਾ ਪਲੇਟਫਾਰਮ ਜਿੱਥੇ ਤੁਸੀਂ ਪੰਜ ਮਿੰਟਾਂ ਵਿੱਚ ਕਿਤਾਬ ਬਾਰੇ ਫੈਸਲਾ ਕਰ ਸਕੋ, ਇਮਾਨਦਾਰੀ ਨਾਲ ਆਪਣੀ ਰੀਡਿੰਗ ਟਰੈਕ ਕਰ ਸਕੋ, ਅਤੇ ਸੱਚਮੁੱਚ ਦੂਜੇ ਪਾਠਕਾਂ ਨਾਲ ਜੁੜ ਸਕੋ — ਸਿਰਫ਼ ਖਲਾਅ ਵਿੱਚ ਇੱਕ ਸਟਾਰ ਰੇਟਿੰਗ ਛੱਡਣ ਦੀ ਬਜਾਏ।",
  whyWeBuiltPara2: "ਹਰ ਕਿਤਾਬ ਪੰਨਾ ਤੁਹਾਨੂੰ ਤੇਜ਼ੀ ਨਾਲ ਫੈਸਲਾ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਨ ਲਈ ਬਣਾਇਆ ਗਿਆ ਹੈ: ਇੱਕ ਅਸਲੀ ਸੰਖੇਪ, ਮੁੱਖ ਨੁਕਤੇ, ਕਮਿਊਨਿਟੀ ਭਾਵਨਾ (ਰੇਟਿੰਗਾਂ, ਮੂਡ, ਰਫ਼ਤਾਰ), ਅਤੇ ਖਰੀਦਣ ਜਾਂ ਸੁਣਨ ਦਾ ਸਿੱਧਾ ਰਸਤਾ — ਪੜ੍ਹਨ ਤੋਂ ਬਾਅਦ ਆਪਣੀ ਤਰੱਕੀ ਟਰੈਕ ਕਰਨ ਅਤੇ ਆਪਣੀ ਸਮੀਖਿਆ ਲਿਖਣ ਦੇ ਸੰਦਾਂ ਨਾਲ।",
  whatYouCanDoTitle: "ਤੁਸੀਂ ਇੱਥੇ ਕੀ ਕਰ ਸਕਦੇ ਹੋ",
  featSummariesTitle: "5-ਮਿੰਟ ਦੇ ਸੰਖੇਪ",
  featSummariesDesc: "ਹਰ ਕਿਤਾਬ ਦੇ ਨਾਲ ਇੱਕ ਸੰਖੇਪ ਸਾਰ ਅਤੇ ਮੁੱਖ ਨੁਕਤੇ ਆਉਂਦੇ ਹਨ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਮਿੰਟਾਂ ਵਿੱਚ ਫੈਸਲਾ ਕਰ ਸਕੋ ਕਿ ਇਹ ਤੁਹਾਡੇ ਸਮੇਂ ਦੇ ਯੋਗ ਹੈ ਜਾਂ ਨਹੀਂ।",
  featReviewsTitle: "ਅਸਲੀ ਕਮਿਊਨਿਟੀ ਸਮੀਖਿਆਵਾਂ",
  featReviewsDesc: "ਅਸਲੀ ਪਾਠਕਾਂ ਤੋਂ ਰੇਟਿੰਗਾਂ, ਲਿਖਤੀ ਸਮੀਖਿਆਵਾਂ, ਅਤੇ ਮੂਡ/ਰਫ਼ਤਾਰ ਟੈਗ — ਸੰਦਰਭ ਤੋਂ ਬਿਨਾਂ ਸਿਰਫ਼ ਇੱਕ ਸਟਾਰ ਔਸਤ ਨਹੀਂ।",
  featShelfTitle: "ਯਾਦ ਰੱਖਣ ਵਾਲੀ ਸ਼ੈਲਫ",
  featShelfDesc: "ਟਰੈਕ ਕਰੋ ਕਿ ਤੁਸੀਂ ਕੀ ਪੜ੍ਹਨਾ ਚਾਹੁੰਦੇ ਹੋ, ਹੁਣ ਕੀ ਪੜ੍ਹ ਰਹੇ ਹੋ (ਤਰੱਕੀ ਨਾਲ), ਅਤੇ ਕੀ ਪੂਰਾ ਕੀਤਾ ਹੈ — ਸਭ ਕੁਝ ਤੁਹਾਡੇ ਖਾਤੇ ਨਾਲ ਸਿੰਕ ਕੀਤਾ ਗਿਆ।",
  featRankingTitle: "ਬੁੱਕਵਰਮ ਰੈਂਕਿੰਗ",
  featRankingDesc: "ਪੜ੍ਹੀਆਂ ਕਿਤਾਬਾਂ, ਲਿਖੀਆਂ ਸਮੀਖਿਆਵਾਂ, ਅਤੇ ਕਮਿਊਨਿਟੀ ਭਾਗੀਦਾਰੀ ਲਈ ਅੰਕ ਕਮਾਓ। ਪੜ੍ਹਦੇ ਹੋਏ ਲੀਡਰਬੋਰਡ ਵਿੱਚ ਚੜ੍ਹੋ।",
  featCommunityTitle: "ਕਮਿਊਨਿਟੀ ਚਰਚਾਵਾਂ",
  featCommunityDesc: "ਕਿਸੇ ਵੀ ਕਿਤਾਬ ਨਾਲ ਜੁੜੀ ਚਰਚਾ ਸ਼ੁਰੂ ਕਰੋ, ਦੂਜੇ ਪਾਠਕਾਂ ਨੂੰ ਜਵਾਬ ਦਿਓ, ਅਤੇ ਇੱਕ ਜਨਤਕ ਰੀਡਿੰਗ ਪ੍ਰੋਫਾਈਲ ਬਣਾਓ।",
  featLanguagesTitle: "21 ਭਾਸ਼ਾਵਾਂ",
  featLanguagesDesc: "ਪੂਰਾ ਇੰਟਰਫੇਸ — ਨੇਵੀਗੇਸ਼ਨ, ਖੋਜ, ਕਿਤਾਬ ਪੰਨੇ, ਡੈਸ਼ਬੋਰਡ — ਮੁੱਖ ਭਾਰਤੀ ਭਾਸ਼ਾਵਾਂ ਸਮੇਤ ਅਨੁਵਾਦਿਤ ਹੈ।",
  activelyGrowingLabel: "ਸਰਗਰਮੀ ਨਾਲ ਵਧ ਰਿਹਾ ਹੈ",
  activelyGrowingPara: "ਬੁੱਕਕਿਊਬਿਟ 21 ਭਾਸ਼ਾਵਾਂ ਵਿੱਚ ਉਪਲਬਧ ਹੈ — ਅੰਗਰੇਜ਼ੀ, ਹਿੰਦੀ, ਬੰਗਾਲੀ, ਤੇਲਗੂ, ਮਰਾਠੀ, ਤਾਮਿਲ, ਗੁਜਰਾਤੀ, ਕੰਨੜ, ਮਲਿਆਲਮ, ਪੰਜਾਬੀ, ਅਤੇ ਉਰਦੂ ਸਮੇਤ, ਸਪੈਨਿਸ਼, ਫਰਾਂਸੀਸੀ, ਜਰਮਨ, ਪੁਰਤਗਾਲੀ, ਇਤਾਲਵੀ, ਰੂਸੀ, ਚੀਨੀ, ਜਾਪਾਨੀ, ਕੋਰੀਆਈ, ਅਤੇ ਅਰਬੀ ਨਾਲ — ਅਤੇ ਨਵੀਆਂ ਕਿਤਾਬਾਂ, ਲੇਖਕ, ਅਤੇ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਨਿਯਮਿਤ ਤੌਰ ਤੇ ਸ਼ਾਮਲ ਕੀਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ।",
