const DICT = { en, hi, ur, ar, es, fr, zh, ja, de, ru, bn, ta, te, mr, gu, kn, ml, pa, pt, it, ko };

export function t(lang) {
  const d = DICT[lang] || en;
  return (key, vars) => {
    let str = d[key] ?? en[key] ?? key;
    if (vars) for (const [k, v] of Object.entries(vars)) str = str.replaceAll(`{${k}}`, v);
    return str;
  };
}
